// Des: Tests for sy-clou-stor and the three S3 vendor presets
// Flo: fake S3 transport (signature checked, paging) > put/get/del/list > presets > key pairs
// I/O: fake HTTP > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const stor = @import("sy-clou-stor.zig"); const base = @import("nt-vend-base.zig"); const s3v4 = @import("sy-clou-s3v4.zig"); const cfgz = @import("cf-conf-load.zig"); const b2zz = @import("sy-clou-b2zz.zig"); const r2zz = @import("sy-clou-r2zz.zig"); const tigr = @import("sy-clou-tigr.zig");
const allo = std.testing.allocator;
const Fake = struct { map: std.StringHashMapUnmanaged([]u8) = .empty, calls: usize = 0, bad2: usize = 0, las4: [128]u8 = undefined, las3: usize = 0,
pub fn deinit(self: *Fake) void { var iter = self.map.iterator(); while (iter.next()) |entr| { allo.free(entr.key_ptr.*); allo.free(entr.value_ptr.*); } self.map.deinit(allo); }
pub fn send(self: *Fake) base.Send { return .{ .ctx2 = self, .call = cal2 }; }
fn cal2(ctx2: *anyopaque, gpaz: std.mem.Allocator, _: std.Io, http: base.Http) anyerror!base.Back { const self: *Fake = @ptrCast(@alignCast(ctx2)); self.calls += 1; if (!std.mem.startsWith(u8, http.auth, "AWS4-HMAC-SHA256 Credential=") or http.ext2.len != 2) self.bad2 += 1; const rest = http.urlz["https://".len..]; const slas = std.mem.findScalar(u8, rest, '/').?; const pqzz = rest[slas..]; const qixz = std.mem.findScalar(u8, pqzz, '?'); const path = if (qixz) |que2| pqzz[0..que2] else pqzz; const query = if (qixz) |que2| pqzz[que2 + 1 ..] else ""; if (std.mem.eql(u8, http.meth, "PUT")) { const key2 = try allo.dupe(u8, path); const val2 = try allo.dupe(u8, http.body); if (self.map.fetchRemove(key2)) |oldz| { allo.free(oldz.key2); allo.free(oldz.value); } try self.map.put(allo, key2, val2); return .{ .code = 200, .body = try gpaz.dupe(u8, "") }; } if (std.mem.eql(u8, http.meth, "DELETE")) { if (self.map.fetchRemove(path)) |oldz| { allo.free(oldz.key2); allo.free(oldz.value); } return .{ .code = 204, .body = try gpaz.dupe(u8, "") }; }
if (query.len == 0) { const val2 = self.map.get(path) orelse return .{ .code = 404, .body = try gpaz.dupe(u8, "") }; return .{ .code = 200, .body = try gpaz.dupe(u8, val2) }; } const numb = @min(query.len, self.las4.len); @memcpy(self.las4[0..numb], query[0..numb]); self.las3 = numb; var keys: std.ArrayList([]const u8) = .empty; defer keys.deinit(allo); var iter = self.map.iterator(); while (iter.next()) |entr| try keys.append(allo, entr.key_ptr.*); std.mem.sort([]const u8, keys.items, {}, struct { fn ltzz(_: void, aaaz: []const u8, bytz: []const u8) bool { return std.mem.lessThan(u8, aaaz, bytz); } }.ltzz); const skip: usize = if (std.mem.indexOf(u8, query, "continuation-token=") != null) 2 else 0; var xmlz: std.ArrayList(u8) = .empty; defer xmlz.deinit(allo); var sho2: usize = 0; for (keys.items, 0..) |key2, ind3| { if (ind3 < skip or sho2 >= 2) continue; const bare = key2["/bkt/".len..]; try xmlz.print(allo, "<Contents><Key>{s}</Key><Size>{d}</Size></Contents>", .{ bare, self.map.get(key2).?.len }); sho2 += 1; } const more = keys.items.len > skip + 2; try xmlz.print(allo, "<IsTruncated>{s}</IsTruncated>{s}", .{ if (more) "true" else "false", if (more) "<NextContinuationToken>tok/1</NextContinuationToken>" else "" }); return .{ .code = 200, .body = try gpaz.dupe(u8, xmlz.items) }; } };
fn mkzz(fakz: *Fake) stor.S3 { return .{ .cred = .{ .akey = "AK", .skey = "SK", .regn = "auto", .host = "h.example.com" }, .bukt = "bkt", .send = fakz.send(), .gpaz = allo }; }
test "put, get, delete round trip, every call is signed" { var fakz: Fake = .{}; defer fakz.deinit(); var s3zz = mkzz(&fakz); const stoz = s3zz.store(); var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); try stoz.put(stoz.ctx2, aren.allocator(), std.testing.io, "runs/a b.pack", "DATA"); const got2 = try stoz.get(stoz.ctx2, aren.allocator(), std.testing.io, "runs/a b.pack"); try std.testing.expectEqualStrings("DATA", got2); try stoz.del2(stoz.ctx2, aren.allocator(), std.testing.io, "runs/a b.pack"); try std.testing.expectError(error.CloudHttp, stoz.get(stoz.ctx2, aren.allocator(), std.testing.io, "runs/a b.pack")); try std.testing.expectEqual(@as(usize, 0), fakz.bad2); }
test "list pages through continuation tokens and filters by prefix query" { var fakz: Fake = .{}; defer fakz.deinit(); var s3zz = mkzz(&fakz); const stoz = s3zz.store(); var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const nams = [_][]const u8{ "runs/1.pack", "runs/2.pack", "runs/3.pack", "runs/4.pack", "runs/5.pack" }; for (nams) |nam2| try stoz.put(stoz.ctx2, aren.allocator(), std.testing.io, nam2, "xyz"); const objs = try stoz.list(stoz.ctx2, aren.allocator(), std.testing.io, "runs/"); try std.testing.expect(objs.len >= 4); try std.testing.expectEqual(@as(u64, 3), objs[0].size); try std.testing.expect(std.mem.indexOf(u8, fakz.las4[0..fakz.las3], "list-type=2&prefix=runs%2F") != null); try std.testing.expect(std.mem.indexOf(u8, fakz.las4[0..fakz.las3], "continuation-token=tok%2F1") != null); }
test "vendor presets: B2 host from region, R2 needs a host, Tigris default host" { var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const pair: stor.Pair = .{ .akey = "a", .skey = "s" }; const conf: cfgz.Conf = .{}; const bbzz = try b2zz.credMake(aren.allocator(), conf.clou_endp.b2zz, pair); try std.testing.expectEqualStrings("s3.us-west-004.backblazeb2.com", bbzz.host); try std.testing.expectError(error.BadConfig, r2zz.credMake(aren.allocator(), conf.clou_endp.r2zz, pair)); const rrzz = try r2zz.credMake(aren.allocator(), .{ .hos4 = "acct.r2.cloudflarestorage.com" }, pair); try std.testing.expectEqualStrings("auto", rrzz.regn); const ttzz = try tigr.credMake(aren.allocator(), conf.clou_endp.tigr, pair); try std.testing.expectEqualStrings("t3.storage.dev", ttzz.host); }
test "key pair needs two non-empty lines" { const pair = try stor.keyzPair(" AKEY \r\n SECRET \nignored"); try std.testing.expectEqualStrings("AKEY", pair.akey); try std.testing.expectEqualStrings("SECRET", pair.skey); try std.testing.expectError(error.NoKey, stor.keyzPair("only one")); try std.testing.expectError(error.NoKey, stor.keyzPair("a\n \n")); try std.testing.expectError(error.NoKey, stor.keyzPair("")); }
